#pragma once

#include "passes/pass.hpp"
#include "problem/problem.hpp"
#include "unified_planning.pb.h" // Generated by protoc

namespace rantanplan::api {

/**
 * @brief Run the full preprocessing pipeline on a problem.
 *
 * Owns pass-list construction, the pre-grounding snapshot for symmetry
 * detection, the pipeline run, the numeric-constraint analysis, and
 * final stats recording. If the result has proven_unsolvable set, the
 * caller must not call solve().
 */
PipelineResult preprocess(Problem problem);

/**
 * @brief Assemble strategy components from the pipeline result and search.
 *
 * Consumes (moves out of) parts of the pipeline result: interference,
 * state constraints, achievers.
 */
PlanGenerationResult solve(PipelineResult& pipeline_result);

/**
 * @brief Export the SMT formula for a fixed timestep instead of solving.
 *
 * Bypasses preprocessing entirely — operates on the raw loaded problem.
 * Returns a process exit code.
 */
int export_formula(const Problem& problem);

} // namespace rantanplan::api
